namespace OpenTPW;

/// <summary>
/// The rides slice's approximation register (docs/OBJECTS.md, "Approximation register"). Each entry is
/// tagged <c>[APPROX:RIDES-NNN]</c> (texture-frame application: <c>MD2-9NN</c>; MD2-900 is retired) at its code site;
/// <see cref="LogOnce"/> lists them at the first catalog load.
/// </summary>
public static class RidesApproximations
{
	public static readonly IReadOnlyList<(string Id, string Rule)> Entries = new[]
	{
		("RIDES-011", "add-on double-layer flags and rotated endpoint mode4 validation are implemented; coaster type21 markers now integrate single-cell preview, live stack payload and teardown. Residual: the kart and water track tool's share of the native sticky tool globals (0x7639E0..0x7639EC) is ported (TrackToolGlobals; ECON-050 retired) and the coaster marker tool's is not modeled (their port is user-approved 2026-10-30 and open); the defensive host owner/generation leases that avoid unconditional native foreign-cell commits are not part of this ID ([EXT:track-tool-owner-leases], user-approved 2026-10-30, against the original's bug); see docs/COASTER-CELL-MARKERS.md"),
		("RIDES-021", "the cursor's cell is the cell of the ray's nearest hit (the hit divided by the cell size, 0x45d560; the click command 0x46c5d0 hands it to 0x524790): the terrain hit (TerrainRayPick, the original's heightfield triangle planes of 0x45bf90) or, when nearer, the first object model the ray meets in 0x45bf90's walk of the cells from the camera (ObjectRayPick and ObjectPickModel: the walk, the edge clamp and the height window of 0x45cdc0 with the owner and height of the cell lookup 0x452ae0, and the model test 0x45d090, as read); the instance's model walk is read except the group pick: the refresh 0x473c30 (0x473a40) that every instance's creation tail runs over every node (0x4638f7..0x463937: node flag 0x10000 on all nodes, model flag 0x40000, fixed objects too; a non-fixed object's vertices are the conformed ones) is ported for the pick, computed at the instance's first model test from the creation-time vertices (the original's lighting reads those normals too, which the draw does not); not ported: the node bits 0x20 and 0x8000 (no shipped object model has them, but the eye views set 0x8000, 0x42ad82, the camera word is saved with its eye bits, 0x42ce1b, and the node-state saver 0x464140 and loader 0x4647a0 keep 0x20 and 0x8000 in a node's saved word, 0x4643b5 and 0x4643bf, which OpenTPW's import does not restore), the group flag 0x80000 that the coaster code sets on its instances (0x434060 at 0x43428b, +0xd4 the creating record, instances of table 0x7a4610; it makes 0x447790 and 0x4477d0 hand the pick the group's member models), the picker's own refresh after a re-conform of the coaster pylon stacks (0x45cecf..0x45ced9 once 0x469a56 sets the model flag again, from 0x432df0 and 0x442f40), and a cell whose second-layer piece instance answers 0x452ae0 (0x53bf30 returns the second-layer record's word +4 for any second-layer cell: a kart or water ride's track tile, a 2 x 2 piece profile map) is not tested, where the original tests the piece's model; the hit instance that 0x45bf90 hands to 0x469340 (0x45ccd5) is the one the hover handler and the click dispatcher pass to 0x469180 (0x486f6b, 0x4874fe, 0x487712, 0x48778d, 0x4878ce, 0x48798b, 0x4bd9ef: the instance's nodes get a private copy of their face normals, node flag 0x1000000 and model flag 0x400000, and 0x469410 and 0x469840 from the frame loop 0x54e301 fill the node colour words with a pulsing colour from the tick), a hover highlight the draw does not have; the hover cell word keeps its previous value when the ray finds nothing (Level.RefreshHoverCell) where the park tools read the pick at the call and act on nothing; the generic sandbox has no heightfield and takes the Z = 0 plane for the terrain hit ([EXT:build-cursor-ground-plane]); the anchor taken from the clicked cell is the original's (0x528b44), so the click is local (W/2, H/2) when each side is odd or at most 5 cells (the only shipped exception is space 3104 Orbiter, 6 x 3: local (3, 1) at 0 degrees, (2, 2) at 90)"),
		("RIDES-031", "a Theme Park Inc world types the footprints of its placed objects through ParkCellMap.WriteFootprint, the port of Theme Park Inc's own placement commit, which is the twin of tp.exe's (the same 24-way cell-type table, 0x6691D8 and 0x6691FC against 0x529D04 and 0x529D24: '@' stamps a type-1 NoModify path cell linked to its path neighbours, 0x668552 against 0x529173, the queue cell and the entrance and exit cells the same sequences); a layout restored from a checkpoint is stamped again when it connects (a checkpoint saved before the footprints were typed also gets the access links its placements lay); not ported: the extra case for the coaster marker type 0x15 (0x6688F0; the slice has no Theme Park Inc coaster), the commit's preview flag modes and effects beyond the cell stamps, and Theme Park Inc's own validator twin of 0x535670 (the typed slice asks tp.exe's)"),
		("RIDES-032", "this simulation updates and poses every instance in its tick, seen or not (the saved node states, picks and the hash must not depend on the camera), where the original's list pass 0x44e410 updates an instance the renderer did not pose in the previous frame without sampling (0x473c70(inst, 0, 8)) and the render callback 0x463030, which the mesh prepare 0x57a750 calls as call eax (so no direct call through +0x140 exists), poses it; the handshake and the drawn reset are ported (flags 0x200000/0x800000, the stored pose restored on return 0x44e380 -> 0x4726d0, which stays in the drawn state until a writer writes the element as tp.exe keeps it, the key table 0x44ab30, the callback offered before any mesh test, hidden or out-of-view parts included); point lights and lamps read the drawn IsNodeHidden, which is harmless because light dummies have no mesh; whether an object is called back is decided here by the view bounds of all its parts together, where the original's scene pass 0x576910 offers it to every object of its always-list and of the terrain cells the view covers"),
		("RIDES-040", "Theme Park Inc fixed scene records saved at (0, 0) use their local model origin; the thing records of the six that have an archive carry the fixed-item default position (128, 128) and angle 0, so the save leaves no transform field unread; how the original places a local-coordinate fixed model at its anchor is not read: a thing's position bytes (+4 and +6 the 1/256 fractions, +5 and +7 the cells) are decoded as (cell + fraction / 256) x 10 only by the camera-target setters 0x503490 and 0x5A1100 (through 0x407793, 0x466FA0, which write the camera words 0xA14480 and 0xA14488), and no other reader of that decoding was found"),
		("RIDES-045", "a Theme Park Inc object that a mod brings into a Theme Park World park runs its original script, but only the script variables Theme Park World's engine writes are driven: the variables the scripts of the three Theme Park Inc worlds declare beyond the standard ride set (VAR_FPBYPASS in 69 scripts, VAR_SPEED in 19, VAR_SPECIAL in 15, the sideshows' VAR_WIN*/VAR_IN*/VAR_TIMEOUT/VAR_WINLANE, the litter bin's VAR_BOMB, VAR_PRANKED, VAR_ONFIRE, VAR_DIRTY, VAR_EMPTY, VAR_FIRERISK, VAR_CONTENTS and VAR_TIMER, the staff rooms' VAR_CLOSED) keep their initial 0, so the branches they guard never run (the litter bin's WAITABS, opcode 45, sits behind VAR_BOMB); what Theme Park Inc's executable writes into them, and when, is not read (the no-CD Game.exe carries no variable names, only the numbered slots \"VAR_%.2ld\" of its script dump, so a writer is found by slot index through each script's own name table, which is not mapped)"),
		// register-empty: the MD2 area has no entry left (tools/fidelity_register.py accepts a register file with this marker).
	};

	private static bool logged;

	public static void LogOnce()
	{
		if ( logged )
			return;
		logged = true;
		foreach ( var (id, rule) in Entries )
			Log?.Warning( $"[APPROX:{id}] {rule}" );
	}
}
